{
  "implementation": "def solve(case):
    attempts = case['attempts']
    max_attempts = case['max_attempts']
    if len(attempts) == 0:
        return {'decision': 'retry', 'memory_append': None, 'next_attempt': 1}
    last = attempts[-1]
    if last['success']:
        return {'decision': 'stop', 'memory_append': None, 'next_attempt': len(attempts)}
    else:
        if len(attempts) >= max_attempts:
            return {'decision': 'stop', 'memory_append': None, 'next_attempt': len(attempts)}
        else:
            earlier_signatures = [a['failure_signature'] for a in attempts[:-1]]
            if last['failure_signature'] in earlier_signatures:
                return {'decision': 'stop', 'memory_append': None, 'next_attempt': len(attempts)}
            else:
                return {
                    'decision': 'retry',
                    'memory_append': {'reflection': last['reflection'], 'signature': last['failure_signature']},
                    'next_attempt': len(attempts) + 1
                }"
}
